prefix-sums.python:
def prefixSums(nums):
    p = [0]
    for x in nums:
        p.append(p[-1] + x)
    return p

prefix-sums.javascript:
function prefixSums(nums) {
  const p = new Array(nums.length + 1).fill(0);
  for (let i = 0; i < nums.length; i++) p[i + 1] = p[i] + nums[i];
  return p;
}

range-sum.python:
def rangeSum(nums, queries):
    p = prefixSums(nums)
    return [p[r + 1] - p[l] for l, r in queries]

range-sum.javascript:
function rangeSum(nums, queries) {
  const p = prefixSums(nums);
  return queries.map(([l, r]) => p[r + 1] - p[l]);
}

is-palindrome.python:
def isPalindrome(s, lo, hi):
    while lo < hi:
        if s[lo] != s[hi]:
            return False
        lo += 1
        hi -= 1
    return True

is-palindrome.javascript:
function isPalindrome(s, lo, hi) {
  if (lo >= hi) return true;
  return s[lo] === s[hi] && isPalindrome(s, lo + 1, hi - 1);
}

lower-bound.python:
def lowerBound(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

lower-bound.javascript:
function lowerBound(nums, target) {
  // Binary lifting: `pos` counts elements known to be < target; try to
  // extend it by decreasing powers of two.
  let pos = 0;
  let step = 1;
  while (step * 2 <= nums.length) step *= 2;
  for (; step >= 1; step = Math.floor(step / 2)) {
    if (pos + step <= nums.length && nums[pos + step - 1] < target) pos += step;
  }
  return pos;
}

count-in-range.python:
def countInRange(nums, lo, hi):
    if lo > hi:
        return 0
    return lowerBound(nums, hi + 1) - lowerBound(nums, lo)

count-in-range.javascript:
function countInRange(nums, lo, hi) {
  if (lo > hi) return 0;
  return lowerBound(nums, hi + 1) - lowerBound(nums, lo);
}

gcd.javascript:
function greatestCommonDivisor(a, b) {
  while (b !== 0) {
    const r = a % b;
    a = b;
    b = r;
  }
  return a;
}

lcm.python:
def leastCommonMultiple(a, b):
    if a == 0 or b == 0:
        return 0
    return a // greatestCommonDivisor(a, b) * b

lcm.javascript:
function leastCommonMultiple(a, b) {
  if (a === 0 || b === 0) return 0;
  return (a / greatestCommonDivisor(a, b)) * b;
}

merge-sorted.python:
def mergeSorted(a, b):
    out = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out

merge-sorted.javascript:
function mergeSorted(a, b) {
  const out = [];
  let i = 0, j = 0;
  while (i < a.length || j < b.length) {
    if (j >= b.length || (i < a.length && a[i] <= b[j])) out.push(a[i++]);
    else out.push(b[j++]);
  }
  return out;
}

merge-sort.python:
def mergeSort(nums):
    if len(nums) <= 1:
        return list(nums)
    mid = len(nums) // 2
    return mergeSorted(mergeSort(nums[:mid]), mergeSort(nums[mid:]))

merge-sort.javascript:
function mergeSort(nums) {
  // Bottom-up: merge runs of width 1, 2, 4, ...
  let runs = nums.map((x) => [x]);
  if (runs.length === 0) return [];
  while (runs.length > 1) {
    const next = [];
    for (let i = 0; i < runs.length; i += 2) {
      next.push(i + 1 < runs.length ? mergeSorted(runs[i], runs[i + 1]) : runs[i]);
    }
    runs = next;
  }
  return runs[0];
}

bfs-distances.python:
from collections import deque

def bfsDistances(n, edges, src):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    dist = [-1] * n
    dist[src] = 0
    queue = deque([src])
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

bfs-distances.javascript:
function bfsDistances(n, edges, src) {
  // Level-by-level frontier instead of a queue.
  const adj = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }
  const dist = new Array(n).fill(-1);
  dist[src] = 0;
  let frontier = [src];
  for (let level = 1; frontier.length; level++) {
    const next = [];
    for (const u of frontier) {
      for (const v of adj[u]) {
        if (dist[v] === -1) { dist[v] = level; next.push(v); }
      }
    }
    frontier = next;
  }
  return dist;
}

shortest-path-len.javascript:
function shortestPathLen(n, edges, src, dst) {
  return bfsDistances(n, edges, src)[dst];
}
